 static int passed,failed;
 static void Check(bool ok,string label){if(ok){passed++;return;}failed++;Console.WriteLine("FAIL "+label);}
 static GameObject Child(Transform p,string n){var g=new GameObject(n);g.transform.parent=p;return g;}
 static GameObject Role<T>(Transform p,string n,float x) where T:Component,new(){var g=Child(p,n);g.Add<T>();g.transform.localPosition=new(x,0,0);return g;}
 static LevelBlock Block(string name,int width){var g=new GameObject(name);var b=g.Add<LevelBlock>();b._dimensionsComputed=true;b._width=width;Child(g.transform,"GameLayer");return b;}
 static Tile MakeTile(Transform p){var g=Role<Tile>(p,"Tile Big 2",0);g.Add<SpriteRenderer>();g.Add<RandomizeSprite>();g.Add<Persistent>().path="Prefabs/Environment/Tile Big";g.Add<BiomeSpriteSwapper>();g.Add<FixedTransform>();g.GetComponent<Tile>().scatterTree=true;return g.GetComponent<Tile>();}
 static LevelBlock BeachSource(bool left){var b=Block(left?"BeachLeft_Blocks_Greece":"BeachRight_Blocks_Greece",16);var g=Role<Beach>(b.transform.GetChild(0),"Beach_greece",left?-.6875f:4.6875f);g.transform.localScale=new(left?1:-1,1,1);g.Add<SpriteRenderer>();g.Add<Persistent>().path=PalaceDedicatedEndpoints.BeachPrefabPath;g.Add<SpriteRendererFX>();g.Add<GAPS>();g.Add<PrefabID>();g.Add<FormationBlocker>();Child(g.transform,"Invisible Wall").Add<BoxCollider2D>();Child(g.transform,"Crown Catcher").Add<BoxCollider2D>().isTrigger=true;return b;}
 sealed class Fixture {
  internal GameObject Owner=new("PrivateOwner");internal LevelBlock Camp=Block("StartingAreaTight_Greece_Blocks",40),Spawn=Block("PlayerSpawn_Blocks_Greece",24),Left=BeachSource(true),Right=BeachSource(false);
  internal Fixture(){Owner.SetActive(false);var c=Camp.transform.GetChild(0);Role<Campfire>(c,"Castle0_greece",0);foreach(var n in new[]{"ShopHammer Placeholder","ShopBow Placeholder","ShopScythe Placeholder"})Role<PrefabPlaceholder>(c,n,0);for(int i=0;i<2;i++)Role<Beggar>(c,"Beggar",i).Add<Animator>();MakeTile(c);var s=Spawn.transform.GetChild(0);Role<PrefabPlaceholder>(s,"Player Placeholder (1)",0);Role<PrefabPlaceholder>(s,"Player Placeholder (2)",-1.12f);Role<Ghost>(s,"Ghost",7.4375f);Role<WreckPlaceholder>(s,"Wreck_Greece",4);Role<BoatSailPosition>(s,"BoatSailPosition_Greece",-5);Role<InfoText>(s,"Hint Crown Loss (1)",0).Add<Persistent>();for(int i=0;i<s.childCount;i++){var t=s.GetChild(i);t.localPosition=new(t.localPosition.x,.875f+i/32f,1f+i/16f);}}
 }
 static bool Build(Fixture f,PalaceLayoutRecipe recipe,out LevelBlock owned,out GameObject left,out GameObject right,out string reason){
  // Baseline invokes the actual old production signature; no alternate geometry algorithm.
  var method=typeof(PalaceDedicatedOwnedBlock).GetMethod("TryBuild",BindingFlags.Static|BindingFlags.NonPublic);
  object[] args=method.GetParameters().Length==10?new object[]{f.Owner,f.Camp,f.Spawn,f.Left,f.Right,recipe,null,null,null,null}:new object[]{f.Owner,f.Camp,f.Spawn,f.Left,f.Right,null,null,null,null};
  bool ok=(bool)method.Invoke(null,args);int index=args.Length-4;owned=(LevelBlock)args[index];left=(GameObject)args[index+1];right=(GameObject)args[index+2];reason=(string)args[index+3];return ok;
 }
 static void Layout(PalaceLayoutRecipe recipe){var f=new Fixture();int rootClones=UObj.BlockCloneCalls;bool ok=Build(f,recipe,out var owned,out var left,out var right,out var reason);Check(ok,recipe.LayoutId+" constructs: "+reason);if(!ok)return;Check(UObj.BlockCloneCalls==rootClones+1,recipe.LayoutId+" single owned block allocation");var layer=owned.transform.GetChild(0);var tiles=layer.Children.Select(x=>x.gameObject.GetComponent<Tile>()).Where(x=>x!=null).OrderBy(x=>x.GetLeft()).ToArray();Check(owned._width==recipe.Width&&owned._left==recipe.Left&&owned._right==recipe.Right,recipe.LayoutId+" cached geometry");Check(tiles.Length==recipe.TileCount,recipe.LayoutId+" exact tile count");for(int i=0;i<tiles.Length;i++)Check(tiles[i].GetLeft()==recipe.Left+i*4,recipe.LayoutId+" tile"+i);Check(layer.childCount==recipe.TileCount+14,recipe.LayoutId+" source-derived exact direct count");Check(left.transform.localPosition.x==recipe.BeachLeftX&&right.transform.localPosition.x==recipe.BeachRightX,recipe.LayoutId+" beach anchors");foreach(var role in f.Spawn.transform.GetChild(0).Children){var clone=layer.Children.Single(x=>x.gameObject.name==role.gameObject.name+"(Clone)");Check(Math.Abs(clone.localPosition.x-(role.localPosition.x+recipe.SpawnRootShiftX))<.001f,recipe.LayoutId+" cluster "+role.gameObject.name);Check(clone.localPosition.y==role.localPosition.y&&clone.localPosition.z==role.localPosition.z&&clone.localScale.x==role.localScale.x&&clone.localScale.y==role.localScale.y&&clone.localScale.z==role.localScale.z,recipe.LayoutId+" preserved role transform "+role.gameObject.name);}Check(f.Camp._width==40&&f.Spawn._width==24&&f.Camp.transform.GetChild(0).childCount==7,recipe.LayoutId+" sources unchanged");Check(tiles.All(t=>!t.scatterTree),recipe.LayoutId+" owned scatter cleared");Check(f.Camp.transform.GetChild(0).Children.Select(x=>x.gameObject.GetComponent<Tile>()).Single(x=>x!=null).scatterTree,recipe.LayoutId+" source scatter retained");}
 static string Fingerprint(LevelBlock source){
  var text=new System.Text.StringBuilder();
  void Visit(Transform node){text.Append(node.Pointer).Append(':').Append(node.gameObject.name).Append(':').Append(node.childCount).Append(':').Append(node.localPosition.x).Append('/').Append(node.localPosition.y).Append('/').Append(node.localPosition.z).Append(':').Append(node.localScale.x).Append('/').Append(node.localScale.y).Append('/').Append(node.localScale.z);
   foreach(var component in node.gameObject.GetComponents<Component>()){text.Append('|').Append(component.GetType().Name).Append('@').Append(component.Pointer);for(Type t=component.GetType();t!=typeof(Component);t=t.BaseType)foreach(var field in t.GetFields(BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly)){if(field.Name=="Children"||field.Name=="owner")continue;object value=field.GetValue(component);text.Append(';').Append(field.Name).Append('=').Append(value);}}
   foreach(var child in node.Children)Visit(child);
  }Visit(source.transform);return text.ToString();
 }
 static void Reject(Action<Fixture> configure,string expected,bool owns=false){var f=new Fixture();configure(f);string camp=Fingerprint(f.Camp),spawn=Fingerprint(f.Spawn),left=Fingerprint(f.Left),right=Fingerprint(f.Right);bool ok=Build(f,PalaceLayoutRecipe.Capital400,out var owned,out var lo,out var ro,out var reason);Check(!ok&&reason.Contains(expected),"reject "+expected+": "+reason);Check((owned!=null)==owns,"failure ownership "+expected);Check(Fingerprint(f.Camp)==camp&&Fingerprint(f.Spawn)==spawn&&Fingerprint(f.Left)==left&&Fingerprint(f.Right)==right,"source unchanged on failure "+expected);UObj.AfterClone=null;UObj.ThrowAtCall=0;}
 static void MutateFinal(Action<Transform> action){UObj.AfterClone=g=>{if(g.GetComponent<Beach>()!=null&&g.transform.localScale.x<0)action(g.transform.parent);};}
 static LevelLayout LayoutFor(Fixture f){var l=new LevelLayout();foreach(var b in new[]{f.Camp,f.Spawn,f.Left,f.Right})l.blocks.Add(b);l.layout.Add(new Placement{block=f.Camp});return l;}
 static void Drafts(){foreach(var recipe in new[]{PalaceLayoutRecipe.Known44,PalaceLayoutRecipe.Capital400}){var f=new Fixture();var layout=LayoutFor(f);var placements=layout.layout;var blocks=layout.blocks;Check(PalaceDedicatedDraftProducer.TryPrepare(f.Owner,layout,f.Camp,f.Spawn,recipe,out var draft,out var owned,out _,out _,out var reason),"draft prepares "+recipe.LayoutId+": "+reason);Check(draft.Count==1&&ReferenceEquals(draft[0],owned)&&owned._width==recipe.Width,"single unpublished draft "+recipe.LayoutId);Check(ReferenceEquals(placements,layout.layout)&&ReferenceEquals(blocks,layout.blocks)&&layout.layout.Count==1&&ReferenceEquals(layout.layout[0].block,f.Camp),"no layout ref publication "+recipe.LayoutId);Check(layout.SharedCalls==1,"shared ledger read once");}
 foreach(string mode in new[]{"shared-placement","shared-ledger","alias","duplicate-beach","unknown-recipe"}){var f=new Fixture();var l=LayoutFor(f);PalaceLayoutRecipe recipe=PalaceLayoutRecipe.Capital400;if(mode=="shared-placement")l.layout[0].fromSharedPool=true;if(mode=="shared-ledger")l.SharedCount=1;if(mode=="duplicate-beach")l.blocks.Add(f.Left);if(mode=="unknown-recipe")recipe=null;int before=UObj.InstantiateCalls;Check(!PalaceDedicatedDraftProducer.TryPrepare(f.Owner,l,f.Camp,mode=="alias"?f.Camp:f.Spawn,recipe,out var draft,out var owned,out _,out _,out _),"draft preflight rejects "+mode);Check(draft==null&&owned==null&&UObj.InstantiateCalls==before,"draft rejection before allocation "+mode);}}
 static int Main(){UObj.ThrowAtCall=0;Layout(PalaceLayoutRecipe.Known44);Layout(PalaceLayoutRecipe.Capital400);
 Reject(f=>{while(f.Camp.transform.GetChild(0).childCount<33)Role<Beggar>(f.Camp.transform.GetChild(0),"Beggar",0).Add<Animator>();},"tree-child-budget:33");
 Reject(f=>{var b=f.Camp.transform.GetChild(0).GetChild(4);for(int i=0;i<9;i++){var a=Child(b,"Node"+i);for(int k=0;k<31;k++)Child(a.transform,"Leaf"+k);}},"tree-node-budget");
 Reject(f=>{var p=f.Camp.transform.GetChild(0).GetChild(4);for(int i=0;i<8;i++)p=Child(p,"Deep"+i).transform;},"tree-depth-budget");
 Reject(f=>Child(f.Spawn.transform.GetChild(0),"Unknown"),"spawn-game-layer-unknown-role");
 Reject(f=>UObj.DestroyImmediate(f.Spawn.transform.GetChild(0).GetChild(0).gameObject),"spawn-prefab-placeholders");
 Reject(f=>f.Spawn._width=28,"spawn-width");
 Reject(f=>f.Camp.transform.GetChild(0).Children.Single(x=>x.gameObject.GetComponent<Tile>()!=null).localScale=new(2,1,1),"prototype-scale");
 Reject(f=>MutateFinal(layer=>MakeTile(layer)),"owned-layer-child-count:115/114",true);
 Reject(f=>MutateFinal(layer=>Role<Beggar>(layer,"Beggar",0).Add<Animator>()),"owned-layer-child-count:115/114",true);
 Reject(f=>MutateFinal(layer=>{var shop=layer.Children.First(x=>x.gameObject.name.StartsWith("Shop"));UObj.DestroyImmediate(shop.gameObject);Role<Beggar>(layer,"Beggar",0).Add<Animator>();}),"owned-camp-roles",true);
 Reject(f=>MutateFinal(layer=>{var shop=layer.Children.First(x=>x.gameObject.name.StartsWith("Shop"));UObj.DestroyImmediate(shop.gameObject);Child(layer,"Unknown");}),"owned-unknown-child",true);
 Reject(f=>UObj.AfterClone=g=>{if(g.GetComponent<Tile>()!=null)for(int i=0;i<33;i++)Child(g.transform,"Extra"+i);},"scan-children-budget:33",true);
 Reject(f=>UObj.ThrowAtCall=UObj.InstantiateCalls+4,"tile-instantiate-exception",true);
 var broken=new Fixture();UObj.AfterClone=g=>{if(g.GetComponent<Beach>()!=null&&g.transform.localScale.x<0)g.transform.localPosition=new(100,0,0);};Check(!Build(broken,PalaceLayoutRecipe.Capital400,out var partial,out var leftHandle,out var rightHandle,out _),"endpoint injected failure rejects");Check(partial!=null&&leftHandle!=null&&rightHandle!=null,"both exclusive endpoint handles retained on right failure");Check(broken.Owner.transform.childCount==1,"helper does not destroy partial root");UObj.AfterClone=null;
 var unknown=new Fixture();int allocations=UObj.InstantiateCalls;Check(!Build(unknown,null,out var nothing,out _,out _,out var why)&&nothing==null&&why=="layout-recipe-unknown"&&allocations==UObj.InstantiateCalls,"unknown recipe rejects before allocation");
 var alternate=new Fixture();Role<Beggar>(alternate.Camp.transform.GetChild(0),"Beggar",2).Add<Animator>();Check(Build(alternate,PalaceLayoutRecipe.Capital400,out var alternateOwned,out _,out _,out _),"accepted source receipt extra retained beggar");Check(alternateOwned.transform.GetChild(0).childCount==115,"output exact budget derived from approved source, not hardcoded114");
 Drafts();Console.WriteLine($"Owned assembly actual full product source: passed={passed} failed={failed}");return failed==0?0:1;}
